# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İKLİMİN ETKİSİ: FİZİKSEL (MEKANİK) VE KİMYASAL ÇÖZÜLME</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">FİZİKSEL (MEKANİK) ÇÖZÜLME</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Koşul: Sıcaklık farkı FAZLA, nem ve yağış AZ.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Mekanizma: Genleşme-büzülme, donma-çözülme, tuz çatlatması.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Sonuç: Kimyasal yapı değişmez, kayaç kum ve çakıla ufalanır.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Dünya: Çöller (Sahra, Orta Asya), karasal iç kesimler, tundra.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Türkiye: İç Anadolu, Doğu Anadolu ve Güneydoğu Anadolu.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">KİMYASAL ÇÖZÜNME</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Koşul: Sıcaklık ve yağış (nem) FAZLA, sıcaklık farkı az.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Mekanizma: Su ve CO₂ ile minerallerin kimyasal ayrışması.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Sonuç: Kayaç yapısı değişir, toprak oluşumu hızlanır.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Dünya: Ekvatoral (Amazon, Kongo), Muson ve ılıman okyanusal.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Türkiye: Karadeniz, Akdeniz, Ege ve Marmara kıyıları.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bitki örtüsü kökleriyle hem fiziksel çatlatma (organik/biyolojik çözülme) hem de organik asitlerle kimyasal çözünme yapar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MAGMATİK VE VOLKANİK KAYAÇLARDA OLUŞAN ÖZEL YER ŞEKİLLERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TOR TOPOĞRAFYASI (GRANİT BLOKLARI)</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Kayaç Türü: Derinlik magmatik kayacı olan GRANİT.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• Süreç: Çatlaklar boyunca fiziksel ve kimyasal ayrışma.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Ayrışan ince malzemenin dış kuvvetlerce taşınması.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Sonuç: Üst üste duran yuvarlaklaşmış dev granit blokları.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Örnek: Aydın-Çine Dağları, Uludağ ve İskoçya.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">PERİBACALARI VE KIRGIBAYIR (TÜF VE BAZALT)</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Kayaç Türü: Altta yumuşak TÜF, üstte sert BAZALT/ANDEZİT.</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• Etkili Kuvvet: Akarsu (sel suları) + Rüzgâr (dolaylı).</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Sert bazalt şapka, altındaki tüf gövdeyi aşınmadan korur.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Kırgıbayır: Kil ve tüflü yamaçların sel sularıyla yarılması.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Örnek: Kapadokya (Ürgüp-Göreme-Avanos), Nallıhan.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Peribacaları hem iç kuvvetlerin (volkanizma) hem de dış kuvvetlerin (sel suları) ortak etkisiyle oluşan akarsu aşınım şeklidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KARST TOPOĞRAFYASI: AŞINIM (ÇÖZÜNME) VE BİRİKİM ŞEKİLLERİ</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">KARSTİK AŞINIM ŞEKİLLERİ (KÜÇÜKTEN BÜYÜĞE)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• 1. Lapya: Kayaç yüzeyindeki en küçük erime olukları (cm-m).</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• 2. Dolin: Lapyaların birleşmesiyle oluşan tava çukurları.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• 3. Uvala: Dolinlerin birleşmesiyle büyüyen çukurluklar.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• 4. Polye (Gölova): En geniş karstik tarım ovaları (TAKKE).</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Yer Altı: Mağara, Galeri, Obruk (çökme) ve Düden (suyutan).</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">KARSTİK BİRİKİM ŞEKİLLERİ VE DAĞILIŞI</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Traverten: Yamaçta CaCO₃ çökelmesi (Denizli - Pamukkale).</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Sarkıt: Mağara tavanından damlayan sudan sarkan çökeller.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• Dikit: Mağara tabanında üst üste biriken kalker sütunları.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Sütun: Sarkıt ve dikitin zamanla birleşmesiyle oluşur.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Türkiye: Akdeniz (Teke-Taşeli: Kalker), Sivas-Çankırı (Jips).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türkiye\'deki başlıca polye ovaları \'TAKKE\' (Tefenni, Acıpayam, Korkuteli, Kestel, Elmalı) şifresiyle kodlanır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
